"""Derive SkyyGear/build_skyygear_0.3.45.py from the GENERATED SkyyGear 0.3.44 (build_skyygear_0.3.44.py = the SET pin, itself GENERATED by
tools/gear_0_3_44_patch.py - edit the patch, never a generated script). Every anchor is asserted once; at the end every change is undone on a
copy and compared with 0.3.44 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/gear_0_3_45_patch.py   then   python SkyyGear/build_skyygear_0.3.45.py   (never --deploy)
      then  python SkyyGear/test_skyygear_0.3.45.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G
import wc15 as WC

NOTE = '''0.3.45 (2026-10-24) = WEAPONCRAFT x1.5 (round wc15, FULL round with SkyyMobs 0.1.19 + SkyyClasses 0.1.48; Accessory Plates HELD; tools/wc15.py). Decision
  (docs/answered/classes.md 2026-10-23 CLASS TREE REBUILD BUILT): "Weaponcraft (old Combat) per-rank numbers to be raised ~x1.5 in a follow-up
  Gear / Mobs / Pets / Accessories balance round (they give ~40-47 % of their old share at Lv 50 at 1 point a level)". Skyy 2026-10-24: "dont
  worry about usage, work through your whole list".
  1. THE FIVE WEAPONCRAFT ROWS SkyyGear applies, per rank x1.5 (ceiling = per x max rank x top count, x1.5 too): Hone Edge +2 -> +3 % weapon
     damage (15 at rank 5), Weak Spot +2 -> +3 % crit chance (9), Crit Mastery +3 -> +4.5 % crit damage (13.5), Gear Resonance +2 -> +3 % damage
     per worn combat armor piece (36 at rank 3 x 4), Weapon Tempering +1 -> +1.5 % per weapon step over Iron (30 at rank 4 x 5). Keys, ranks
     and the Server Setup rows (Gear -> Stats, Advanced) are unchanged - only their defaults move. tools/trees_v3_effects.py is NOT edited
     (other builders import it): tools/wc15.py apply() swaps the five rows in memory right after this script imports the table, so every
     number generated from it (V3P / V3X, loadV3's built-in numbers, V3_TEXT, the kit rows + help, GearV3.PER) carries the new value.
  2. ONE-TIME UPDATE GearCfg.migrateWc15 (PROJECT-RULES 4; the migrate39 machinery, generated by tools/wc15.py java()): an existing
     Skyy_SkyyGear/trees.properties line still holding the 0.3.44 default (one plain line, the last entry of its key) moves to the new one; a
     custom value is kept + one INFO note; a missing line = the new built-in number. History copy first (verified), atomic write (ISO-8859-1,
     the file's own line endings), one config-changes.log line per moved line (Undo in Server Setup -> Changes), the marker comment last
     ("# wc15 Weaponcraft x1.5 ..."; a fresh 0.3.45 file carries it, so it never runs there). setup(): right after migrate39, before load().
  SAVED DATA: player data none; trees.properties as above. No command / system / class (the update lives in GearCfg).
  ROLLBACK to 0.3.44: Undo the wc15 rows in Server Setup -> Changes first (0.3.44 would read the raised numbers as admin values and keep
  them); the marker comment is ignored by 0.3.44. No floor of its own (sits above the gear044 floor).
'''

P = G.Patch(os.path.join(ROOT, "SkyyGear", "build_skyygear_0.3.44.py"), os.path.join(ROOT, "SkyyGear", "build_skyygear_0.3.45.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.3.44"') and P.has("topTag(") and not P.has("migrateWc15"), "not the generated SkyyGear 0.3.44 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("mk(\"")

P.rep('''"""SkyyGear 0.3.44 - build script (javassist via jpype). GENERATED by tools/gear_0_3_44_patch.py from the SET pin 0.3.43 (itself GENERATED by
tools/gear_0_3_43_patch.py) - edit the patch, never this file. Run: python SkyyGear/build_skyygear_0.3.44.py -> SkyyGear/SkyyGear-0.3.44.jar
(never --deploy). Harness: python SkyyGear/test_skyygear_0.3.44.py.
''', '''"""SkyyGear 0.3.45 - build script (javassist via jpype). GENERATED by tools/gear_0_3_45_patch.py from the SET pin 0.3.44 (itself GENERATED by
tools/gear_0_3_44_patch.py) - edit the patch, never this file. Run: python SkyyGear/build_skyygear_0.3.45.py -> SkyyGear/SkyyGear-0.3.45.jar
(never --deploy). Harness: python SkyyGear/test_skyygear_0.3.45.py.

''' + NOTE + '''
0.3.44 notes (SkyyGear 0.3.44 - generated by tools/gear_0_3_44_patch.py from the SET pin 0.3.43; harness test_skyygear_0.3.44.py):
''')
P.rep('VERSION = "0.3.44"\n', 'VERSION = "0.3.45"\n')

# 1. the five Weaponcraft rows x1.5, in memory, before anything is generated from the table
P.rep('''import trees_v3_effects as _V3E
# 0.3.32 fixer: the Skill Trees 3 rows' numbers''', '''import trees_v3_effects as _V3E
import wc15 as _WC15
# 0.3.45 (wc15): the five Weaponcraft rows SkyyGear applies x1.5 (tools/wc15.py; 0 = the shared table already holds the new numbers)
_WC15_N = _WC15.apply(_V3E, "SkyyGear")
assert _WC15_N in (0, 5) and [(_e[2], _e[5]) for _e in _V3E.rows("SkyyGear") if _e[0] == "Combat"] == [(_r[2], _r[5]) for _r in _WC15.ROWS["SkyyGear"]], "0.3.45: the Weaponcraft rows"
print("0.3.45 wc15: %d Weaponcraft rows x1.5 (%s)" % (len(_WC15.ROWS["SkyyGear"]), ", ".join("%s %s" % (_m[0], _m[2]) for _m in _WC15.mig_rows(_V3E, "SkyyGear") if _m[0].endswith(".per"))))
# 0.3.32 fixer: the Skill Trees 3 rows' numbers''')

# 2. the one-time trees.properties update (after the kit's emit: it calls CfgFile / CfgRows / CfgHist / CfgLog)
P.rep('''# 0.2.1 ready line part: the base stats in force (live values)''', '''# ---- 0.3.45 ONE-TIME UPDATE migrateWc15 (wc15; PROJECT-RULES section 4; tools/wc15.py java() = the migrate39 machinery for trees.properties):
# Skyy_SkyyGear/trees.properties lines still on the 0.3.44 Weaponcraft defaults -> x1.5 (custom values kept + noted), History copy verified
# first, one change-log line each (Undo in Server Setup -> Changes), the marker comment last (a fresh 0.3.45 file carries it)
_WCF, _WCM = _WC15.java(_V3E, "SkyyGear", "Gear", "@PKG@.Gear.info", "@PKG@.Gear.warn")
for _d in _WCF:
    F(gcf, _d)
for _m in _WCM:
    M(gcf, _m)
assert _WC15.MARK_ID in _V3E.cfg_text("SkyyGear"), "0.3.45: a fresh trees.properties carries the wc15 marker"
# 0.2.1 ready line part: the base stats in force (live values)''')
P.rep('''  @PKG@.GearCfg.migrate39();            // 0.3.39: the Untiered bands at the end of each zone (only the untouched 0.3.38 defaults)
''', '''  @PKG@.GearCfg.migrate39();            // 0.3.39: the Untiered bands at the end of each zone (only the untouched 0.3.38 defaults)
  @PKG@.GearCfg.migrateWc15(@PKG@.GearCfg.FILE == null ? null : @PKG@.GearCfg.FILE.toAbsolutePath().getParent());          // 0.3.45 (wc15): trees.properties Weaponcraft rows x1.5 (only the untouched 0.3.44 defaults)
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("mk(\"") == CLS0, "0.3.45: no class / command / system"
_i = P.s.index
assert _i("import wc15 as _WC15") < _i("F(gcf, _V3E.cfg_text_field(\"SkyyGear\"))") < _i("kit = CFG.emit(pool, PKG, MOD=\"SkyyGear\"") < _i("_WCF, _WCM = _WC15.java(")
assert _i("_GV3 = _V3E.rows(\"SkyyGear\")") > _i("_WC15_N = _WC15.apply(")
P.finish()
print("wrote", P.dst)
